type Produk = { id: string; name: string; price: number };

function isProduk(x: unknown): x is Produk {
  return (
    typeof x === "object" && x !== null &&
    "id" in x && typeof x.id === "string" &&
    "name" in x && typeof x.name === "string" &&
    "price" in x && typeof x.price === "number"
  );
}
async function ambilProduk(id: string): Promise<Produk> {
  const res = await fetch("https://api.toko.contoh/products/" + id);
  if (!res.ok) throw new Error("HTTP " + res.status);
  const data: unknown = await res.json();
  if (!isProduk(data)) throw new Error("Data produk tidak valid");
  return data;
}
const kopi = await ambilProduk("P01");
console.log(kopi.name, kopi.price);
try {
  await ambilProduk("P99");
} catch (e) {
  if (e instanceof Error) console.log("Gagal:", e.message);
}

