function isAngka(x: unknown): x is number {
  return typeof x === "number" && !Number.isNaN(x);
}
const daftar: unknown[] = [5, "7", 3, null, NaN];
const angka = daftar.filter(isAngka);
console.log(angka.length, angka.reduce((a, b) => a + b, 0));

